/** Flate-komprimierte Liberation Sans und sRGB-Profil für die ZUGFeRD-Rechnung. */
const REGULAR_B64 = "";
const BOLD_B64 = "";
const ICC_B64 = "";

function decode(value: string): Uint8Array {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

export const INVOICE_FONT_REGULAR = decode(REGULAR_B64);
export const INVOICE_FONT_BOLD = decode(BOLD_B64);
export const INVOICE_ICC = decode(ICC_B64);

